import XCTest

final class RqProof:XCTestCase {
 func make(_ n:Int,_ ko:Bool)->RqS{var s=RqS(title:"Test cup",place:"Pitch",knockout:ko,start:Date(timeIntervalSince1970:1_800_000_000),interval:7,teams:(1...n).map{RqT(name:"Team \($0)")});s.generate();return s}
 func testRoundRobinAllSizes(){for n in 2...32{let s=make(n,false);XCTAssertEqual(s.next?.date,s.start);XCTAssertEqual(s.games.count,n*(n-1)/2);var pairs=Set<String>();for g in s.games{XCTAssertNotNil(g.a);XCTAssertNotNil(g.b);pairs.insert([g.a!,g.b!].sorted().joined(separator:"/"))};XCTAssertEqual(pairs.count,s.games.count);for r in s.rounds{let ids=s.games.filter{$0.round == r}.flatMap{[$0.a!,$0.b!]};XCTAssertEqual(Set(ids).count,ids.count)}}}
 func testKnockoutAllSizes(){for n in 2...32{var s=make(n,true);XCTAssertEqual(s.next?.date,s.start);var played=0;for i in s.games.indices {if s.games[i].a != nil && s.games[i].b != nil {var m=s.games[i];m.x=2;m.y=1;m.stamp=Date();XCTAssertTrue(s.valid(m));s.put(m);played += 1}};XCTAssertEqual(played,n-1);XCTAssertEqual(s.champions.count,1)}}
 func testStandingsAndPenalties(){var s=make(3,false);var m=s.games[0];m.x=2;m.y=1;s.put(m);XCTAssertEqual(s.table[0].points,3);XCTAssertEqual(s.table[0].diff,1);var k=make(4,true);var g=k.games[0];g.x=1;g.y=1;XCTAssertFalse(k.valid(g));g.px=4;g.py=3;XCTAssertTrue(k.valid(g));k.put(g);XCTAssertEqual(k.games.last?.a,g.a)}
 func testCorrectionClearsDescendants(){var s=make(4,true);for i in s.games.indices{var m=s.games[i];m.x=2;m.y=0;s.put(m)};XCTAssertEqual(s.champions.count,1);var m=s.games[0];m.x=0;m.y=2;s.put(m);XCTAssertNil(s.games.last?.x);XCTAssertTrue(s.champions.isEmpty)}
 func testVotesAndRoundRules(){var s=make(2,false);let p=RqP(name:"Alex",team:s.teams[0].id);s.teams[0].players=[p];s.ballot(round:1,player:p.id,voter:"one");XCTAssertTrue(s.votes.isEmpty);var m=s.games[0];m.x=1;m.y=0;s.put(m);s.ballot(round:1,player:p.id,voter:"one");s.ballot(round:1,player:p.id,voter:"one");XCTAssertEqual(s.votes.count,1);XCTAssertEqual(s.leaders(1).first?.1,1);s.blocked=["one"];XCTAssertTrue(s.leaders(1).isEmpty)}
 @MainActor func testLocalDeletionAndCertificate() async throws {
  let q=RqVault();q.box=RqArchive();var s=make(2,true);var m=s.games[0];m.x=1;m.y=0;s.put(m);q.add(s);q.box.nickname="Organizer";q.write();let pdf=try RqPaper.make(s,s.champions[0]);let bytes=try Data(contentsOf:pdf);XCTAssertTrue(bytes.starts(with:Data("%PDF".utf8)));let proof=XCTAttachment(data:bytes,uniformTypeIdentifier:"com.adobe.pdf");proof.name="winner-certificate.pdf";proof.lifetime = .keepAlways;add(proof);let folder=FileManager.default.urls(for:.applicationSupportDirectory,in:.userDomainMask)[0];let recovery=folder.appendingPathComponent("recovery-unit.json");try JSONEncoder().encode(q.box).write(to:recovery);await q.erase();XCTAssertTrue(q.box.tournaments.isEmpty);XCTAssertTrue(q.box.nickname.isEmpty);XCTAssertFalse(FileManager.default.fileExists(atPath:pdf.path));XCTAssertFalse(FileManager.default.fileExists(atPath:recovery.path));let saved=try JSONDecoder().decode(RqArchive.self,from:Data(contentsOf:folder.appendingPathComponent("neighborhood-v3.json")));XCTAssertTrue(saved.tournaments.isEmpty)
 }
 func testMergeAndDisk() throws {var a=make(4,false);var b=a;var x=a.games[0];x.x=1;x.y=0;x.stamp=Date(timeIntervalSince1970:100);a.put(x);var y=b.games[1];y.x=3;y.y=1;y.stamp=Date(timeIntervalSince1970:200);b.put(y);let m=RqS.merge(a,b);XCTAssertEqual(m.completed,2);XCTAssertEqual(try JSONDecoder().decode(RqS.self,from:JSONEncoder().encode(m)),m)}
 func testRoundEligiblePlayers(){var s=make(3,true);for i in s.teams.indices{s.teams[i].players=[RqP(name:"Player \(i)",team:s.teams[i].id)]};var m=s.games.first{$0.a != nil && $0.b != nil}!;m.x=1;m.y=0;s.put(m);s.ballot(round:1,player:s.teams[0].players[0].id,voter:"one");XCTAssertTrue(s.votes.isEmpty);s.ballot(round:1,player:s.teams[1].players[0].id,voter:"one");XCTAssertEqual(s.votes.count,1);var f=s.games.last!;f.x=1;f.y=0;s.put(f);s.ballot(round:2,player:s.teams[2].players[0].id,voter:"one");XCTAssertFalse(s.votes.contains{$0.round == 2});s.ballot(round:2,player:s.teams[0].players[0].id,voter:"one");XCTAssertTrue(s.votes.contains{$0.round == 2});m.x=0;m.y=1;s.put(m);XCTAssertFalse(s.votes.contains{$0.round == 2});XCTAssertTrue(s.leaders(2).isEmpty)}
 func testScoreValidation(){var s=make(2,false);let p=RqP(name:"Alex",team:s.teams[0].id);s.teams[0].players=[p];var m=s.games[0];m.x=1;m.y=0;m.goals=[p.id:2];XCTAssertFalse(s.valid(m));m.goals=[p.id:1];XCTAssertTrue(s.valid(m));m.x = -1;XCTAssertFalse(s.valid(m))}
 func testCalendarDaysAcrossDST(){let old=NSTimeZone.default;defer{NSTimeZone.default=old};NSTimeZone.default=TimeZone(identifier:"Europe/Berlin")!;let d=Calendar.current.date(from:DateComponents(year:2027,month:3,day:27,hour:10))!;var s=RqS(title:"DST",place:"Pitch",knockout:false,start:d,interval:7,teams:(1...4).map{RqT(name:"Team \($0)")});s.generate();for r in s.rounds{let first=s.games.filter{$0.round == r}.map(\.date).min()!;XCTAssertEqual(Calendar.current.component(.hour,from:first),10)}}
 @MainActor func testStaleReportRejected() async {let q=RqVault();q.box=RqArchive();var s=make(4,true);for i in s.games.indices{var m=s.games[i];m.x=1;m.y=0;s.put(m)};q.add(s);let stale=s.games.last!;var changed=s.games[0];changed.x=0;changed.y=1;q.report(changed,in:s);XCTAssertNil(q.active?.games.last?.x);q.report(stale,in:s);XCTAssertNil(q.active?.games.last?.x);XCTAssertFalse(q.alert.isEmpty);q.alert="";await q.erase()}
 @MainActor func testUserJourney(){
  let app=XCUIApplication();app.launchArguments=["-AppleLanguages","(en)","-AppleLocale","en_US"];app.launch()
  if !app.buttons["createCup"].waitForExistence(timeout:3){app.buttons["Tournaments"].tap();app.buttons["New tournament"].tap()}else{app.buttons["createCup"].tap()};do{app.textFields["cupName"].tap();app.textFields["cupName"].typeText("Courtyard Sunday Cup");let teams=app.textViews["teamNames"];teams.tap();teams.typeText("Vila Verde\nEstrela do Sul\nUnião da Praça\nJardim FC");app.buttons["saveCup"].tap()}
  XCTAssertTrue(app.staticTexts["Courtyard Sunday Cup"].firstMatch.waitForExistence(timeout:5));shot("01-overview")
  app.buttons["Fixtures"].firstMatch.tap();XCTAssertTrue(app.buttons["match-1-0"].waitForExistence(timeout:5));shot("02-fixtures");app.buttons["match-1-0"].tap();XCTAssertTrue(app.buttons["saveReport"].waitForExistence(timeout:5));app.buttons["homeScore-Increment"].tap();app.buttons["saveReport"].tap()
  app.buttons["Standings"].firstMatch.tap();shot("03-standings");app.buttons["Community"].firstMatch.tap();shot("04-community");app.terminate();app.launch();XCTAssertTrue(app.staticTexts["Courtyard Sunday Cup"].firstMatch.waitForExistence(timeout:5))
 }
 @MainActor func testKnockoutCertificate(){
  let app=XCUIApplication();app.launchArguments=["-AppleLanguages","(en)","-AppleLocale","en_US"];app.launch()
  if app.buttons["createCup"].waitForExistence(timeout:3){app.buttons["createCup"].tap()}else{app.buttons["Tournaments"].tap();app.buttons["New tournament"].tap()}
  let name=app.textFields["cupName"];name.tap();name.typeText("Praça Final");app.segmentedControls.buttons["Knockout"].tap();app.textViews["teamNames"].tap();app.textViews["teamNames"].typeText("Verde FC\nAmigos FC");app.buttons["saveCup"].tap();app.buttons["Fixtures"].firstMatch.tap();app.buttons["match-1-0"].tap();app.buttons["homeScore-Increment"].tap();app.buttons["saveReport"].tap();app.buttons["Overview"].firstMatch.tap();let cert=app.buttons["Share winner certificate"];if !cert.isHittable{app.swipeUp()};XCTAssertTrue(cert.waitForExistence(timeout:5));cert.tap();shot("05-certificate-share")
 }
 @MainActor func testNotificationDenial() throws {
  let app=XCUIApplication();app.launchArguments=["-AppleLanguages","(en)","-AppleLocale","en_US"];app.launch();app.buttons["Settings"].tap();let toggle=app.switches["Upcoming rounds and missing reports"];XCTAssertTrue(toggle.waitForExistence(timeout:5));if !toggle.isHittable{app.swipeUp()};toggle.coordinate(withNormalizedOffset:CGVector(dx:0.92,dy:0.5)).tap();let system=XCUIApplication(bundleIdentifier:"com.apple.springboard");var prompt=system.alerts.firstMatch;if !prompt.waitForExistence(timeout:8){let alternative=app.alerts.firstMatch;if alternative.buttons.matching(NSPredicate(format:"label MATCHES[c] %@",".*(Don.*Allow|Não Permitir|No permitir|Nicht erlauben|Ne pas autoriser|Non consentire|Не разрешать).*")).firstMatch.exists{prompt=alternative}else if app.alerts["Please check"].exists{shot("08-notifications-unavailable");app.alerts.buttons["OK"].tap();XCTAssertEqual(toggle.value as? String,"0");throw XCTSkip("The simulator did not offer native notification authorization; the unavailable-permission fallback passed.")}else{XCTFail("No authorization prompt or unavailable-permission message");return}};let deny=prompt.buttons.matching(NSPredicate(format:"label MATCHES[c] %@",".*(Don.*Allow|Não Permitir|No permitir|Nicht erlauben|Ne pas autoriser|Non consentire|Не разрешать).*")).firstMatch;XCTAssertTrue(deny.exists);deny.tap();XCTAssertTrue(app.alerts["Please check"].waitForExistence(timeout:5));shot("08-notifications-denied");app.alerts.buttons["OK"].tap();XCTAssertEqual(toggle.value as? String,"0")
 }
 @MainActor func testPortugueseAndOffline(){
  let app=XCUIApplication();app.launchArguments=["-AppleLanguages","(pt-BR)","-AppleLocale","pt_BR"];app.launch();XCTAssertTrue(app.buttons["Visão geral"].firstMatch.waitForExistence(timeout:5));shot("06-portuguese");app.buttons["Ajustes"].tap();XCTAssertTrue(app.staticTexts["Perfil do organizador"].waitForExistence(timeout:5));let sync=app.buttons["Sincronizar torneios"];sync.tap();XCTAssertTrue(app.alerts["Confira"].waitForExistence(timeout:20));shot("07-offline-cloud");app.alerts.buttons["OK"].tap()
 }
 func shot(_ name:String){let a=XCTAttachment(screenshot:XCUIScreen.main.screenshot());a.name=name;a.lifetime = .keepAlways;add(a)}
}
